CREATE TABLE "avisos_mantenimiento" ("id" TEXT NOT NULL PRIMARY KEY,"empresaId" TEXT NOT NULL DEFAULT '1',"equipoId" TEXT NOT NULL,"prioridad" TEXT NOT NULL DEFAULT 'MEDIA',"estado" TEXT NOT NULL DEFAULT 'ABIERTO',"titulo" TEXT NOT NULL,"sintoma" TEXT NOT NULL,"equipoDetenido" BOOLEAN NOT NULL DEFAULT false,"fechaDeteccion" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"usuarioId" TEXT NOT NULL,"usuarioNombre" TEXT NOT NULL,"creadoEn" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"descartadoEn" DATETIME,"motivoDescarte" TEXT,CONSTRAINT "avisos_mantenimiento_equipoId_fkey" FOREIGN KEY ("equipoId") REFERENCES "equipos"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "avisos_mantenimiento_empresaId_estado_prioridad_idx" ON "avisos_mantenimiento"("empresaId","estado","prioridad");
ALTER TABLE "ordenes_mantenimiento" ADD COLUMN "avisoMantenimientoId" TEXT REFERENCES "avisos_mantenimiento"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE UNIQUE INDEX "ordenes_mantenimiento_avisoMantenimientoId_key" ON "ordenes_mantenimiento"("avisoMantenimientoId");
